116	            .filter(fs -> !replacedFileIds.contains(fs.getFileId()))
117	            .sorted(Comparator.comparingLong((FileSlice fs) ->
118	                fs.getBaseFile().map(HoodieBaseFile::getFileSize).orElse(0L)).reversed())
